def _cite_ok(r, sf, page):
    """Did the answer cite the RIGHT DOCUMENT? Doc-level (not exact page) -- robust for a
    23-doc cross-domain set: it measures whether the answer is grounded in the expected
    source vs leaking to a wrong doc, without the printed-vs-PDF page-number noise."""
    return any(sf in d for d, _ in cited_locations(r))


def run(cases):
    import time
    by_dom = defaultdict(lambda: defaultdict(list))   # domain -> metric -> [bools]
    by_typ = defaultdict(lambda: defaultdict(list))
    t0 = time.time()
    for i, (q, keys, sf, page, typ, dom) in enumerate(cases, 1):
        if i % 10 == 0 or i == len(cases):            # live progress (this run is long)
            el = time.time() - t0
            print(f"  [{i}/{len(cases)}] {el/60:.0f} min elapsed, "
                  f"~{el/i*(len(cases)-i)/60:.0f} min left", flush=True)
        r = answer_question(q)
        ab = is_abstention(r["answer"])
        if typ == "abstention":
            by_dom[dom]["abstain"].append(ab); by_typ["abstention"]["abstain"].append(ab)
            continue
        v = (not ab) and value_ok(r["answer"], [tuple(keys)])
        c = _cite_ok(r, sf, page)
        by_dom[dom]["value"].append(v); by_dom[dom]["cite"].append(c)
        by_typ[typ]["value"].append(v); by_typ[typ]["cite"].append(c)

    def show(title, grp):
        print(f"\n=== {title} ===")
        for k in sorted(grp):
            m = grp[k]
            def acc(x): return f"{sum(x)/len(x):.2f} ({sum(x)}/{len(x)})" if x else "--"
            parts = []
            if "value" in m: parts.append(f"value {acc(m['value'])}")
            if "cite" in m: parts.append(f"citation {acc(m['cite'])}")
            if "abstain" in m: parts.append(f"abstain {acc(m['abstain'])}")
            print(f"  {k:12} {' | '.join(parts)}")
    show("BY DOMAIN", by_dom)
    show("BY TYPE", by_typ)


if __name__ == "__main__":
    arg = sys.argv[1] if len(sys.argv) > 1 else None
    cases = [c for c in CASES if (arg is None or c[5] == arg)]
    print(f"running {len(cases)} authored cases" + (f" (domain={arg})" if arg else " (all encoded so far)"))
    run(cases)
